create table control_feature_flags(id uuid primary key default gen_random_uuid(),flag_key text not null unique,description text not null,enabled_by_default boolean not null default false,status text not null check(status in('draft','active','archived')),updated_by uuid not null references internal_users(id),updated_at timestamptz not null default now());
create table control_feature_targets(id uuid primary key default gen_random_uuid(),feature_flag_id uuid not null references control_feature_flags(id) on delete cascade,customer_account_id uuid not null references customer_accounts(id) on delete cascade,enabled boolean not null,reason text not null check(length(trim(reason))>0),updated_by uuid not null references internal_users(id),updated_at timestamptz not null default now(),unique(feature_flag_id,customer_account_id));
create table ai_operation_traces(id uuid primary key default gen_random_uuid(),customer_account_id uuid references customer_accounts(id) on delete set null,operation text not null,provider text not null,model text not null,status text not null check(status in('started','succeeded','failed','blocked')),input_tokens int check(input_tokens>=0),output_tokens int check(output_tokens>=0),latency_ms int check(latency_ms>=0),sources_offered jsonb not null default '[]',sources_cited jsonb not null default '[]',error_code text,request_id text not null,occurred_at timestamptz not null default now());
create table system_component_status(id uuid primary key default gen_random_uuid(),component_key text not null unique,adapter_name text not null,state text not null check(state in('operational','degraded','outage','unknown','not_configured')),detail text not null,observed_at timestamptz,reported_at timestamptz not null default now(),check(state not in('operational','degraded','outage') or observed_at is not null));
alter table control_feature_flags enable row level security;alter table control_feature_targets enable row level security;alter table ai_operation_traces enable row level security;alter table system_component_status enable row level security;
grant select,insert,update on control_feature_flags,control_feature_targets,system_component_status to authenticated;grant select,insert on ai_operation_traces to authenticated;
create policy flags_select on control_feature_flags for select using(is_active_internal_user());create policy flags_write on control_feature_flags for all using(internal_has_role(array['super_admin','operations','product']::internal_role[])) with check(internal_has_role(array['super_admin','operations','product']::internal_role[]));create policy targets_select on control_feature_targets for select using(is_active_internal_user());create policy targets_write on control_feature_targets for all using(internal_has_role(array['super_admin','operations','product']::internal_role[])) with check(internal_has_role(array['super_admin','operations','product']::internal_role[]));
create policy ai_traces_select on ai_operation_traces for select using(internal_has_role(array['super_admin','operations','product']::internal_role[]));create policy ai_traces_insert on ai_operation_traces for insert with check(internal_has_role(array['super_admin','operations','product']::internal_role[]));create policy system_status_select on system_component_status for select using(is_active_internal_user());create policy system_status_write on system_component_status for all using(internal_has_role(array['super_admin','operations','product']::internal_role[])) with check(internal_has_role(array['super_admin','operations','product']::internal_role[]));
